  | 'Middle East'
  | 'Asia'
  | 'Oceania';

export interface City {
  id: string;
  name: string;
  country: string;
  region: WorldRegion;
  timezone: string;
}

export interface AvailabilitySettings {
  wakeHour: number; // 0 - 23
  sleepHour: number; // 0 - 23
  timeFormat: TimeFormat;
}

export interface PersistedState {
  cityIds: string[];
  mode: AppMode;
  settings: AvailabilitySettings;
